'use strict';
const lessons=[
{id:'salah',name:'Salah',ar:'الصلاة',label:'Prescribed prayer',verse:'4:103',url:'https://quran.com/4/103',text:'Salah is prescribed prayer in Islam. It has appointed times and is an act of worship directed to Allah. In this lesson, the key idea is that Salah is a regular religious duty, not simply a name for any quiet moment.',key:'Appointed times are part of the meaning of prescribed prayer.',pre:['Which description best fits Salah?',['Any quiet moment, without a prescribed form','Prescribed prayer at appointed times','Only prayer during an emergency'],1],post:['A learner says: “Salah is only something done when a person feels worried.” What is missing?',['Its place as prescribed prayer at appointed times','A requirement to be worried first','Nothing; that is the complete meaning'],0],reference:'Salah is prescribed prayer with appointed times; it is not limited to moments of worry.',prompt:'How would you explain the difference between Salah and a general quiet moment?'},
{id:'sawm',name:'Sawm',ar:'الصيام',label:'Fasting',verse:'2:183',url:'https://quran.com/2/183',text:'Sawm means fasting. The Qur’an presents fasting as a prescribed act of worship connected with developing mindfulness of Allah. This lesson focuses on its religious purpose, rather than treating fasting only as a diet or a physical challenge.',key:'The spiritual purpose matters alongside the outward practice.',pre:['What does this lesson emphasize about Sawm?',['It is only a diet','It is a contest in endurance','It is worship connected with mindfulness of Allah'],2],post:['Which explanation preserves the purpose highlighted in Qur’an 2:183?',['Fasting is valuable only for changing body weight','Fasting is prescribed worship that encourages mindfulness of Allah','Fasting has no purpose beyond hunger'],1],reference:'Sawm is fasting as worship, with a purpose connected to mindfulness of Allah, not merely a diet.',prompt:'What is missing when Sawm is described only as “not eating”?'},
{id:'zakat',name:'Zakat',ar:'الزكاة',label:'Obligatory giving',verse:'9:60',url:'https://quran.com/9/60',text:'Zakat is obligatory giving subject to religious rules. Qur’an 9:60 identifies categories of recipients, including poor and needy people. This introduction focuses on the fact that Zakat has designated recipients. It does not calculate anyone’s obligation or decide individual eligibility.',key:'Zakat is governed by rules, including who may receive it.',pre:['Which description best fits Zakat?',['Giving governed by religious rules and designated recipients','Any purchase that makes someone happy','An unrestricted personal gift'],0],post:['Someone says: “Zakat can be spent on absolutely anything I choose.” Which idea needs clarification?',['Zakat is a type of shopping','Zakat has designated recipient categories','Zakat has no connection with people in need'],1],reference:'Zakat is obligatory giving with conditions and designated recipient categories; it is not unrestricted spending.',prompt:'Why does identifying eligible recipients matter when explaining Zakat?'},
{id:'sadaqah',name:'Sadaqah',ar:'الصدقة',label:'Charitable giving',verse:'2:261',url:'https://quran.com/2/261',text:'In this beginner lesson, Sadaqah refers to voluntary charitable giving. Qur’an 2:261 illustrates the reward associated with spending in the way of Allah. Here we focus on generosity and its religious meaning. The word can have broader uses in religious texts, so context matters.',key:'This lesson uses Sadaqah for voluntary giving; do not assume every use of the word has this narrow meaning.',pre:['How is Sadaqah used in this beginner lesson?',['A required fee for using this app','Voluntary charitable giving','A calculation of an individual’s Zakat'],1],post:['Why should we pay attention to context when encountering the word Sadaqah?',['The word always means a commercial loan','Its meaning is unrelated to giving','Religious texts may use it more broadly than this lesson’s voluntary-giving focus'],2],reference:'This lesson focuses on Sadaqah as voluntary giving, while recognizing that its usage in religious texts can be broader.',prompt:'Explain this lesson’s use of Sadaqah, including why context matters.'},
{id:'hajj',name:'Hajj',ar:'الحج',label:'Pilgrimage',verse:'3:97',url:'https://quran.com/3/97',text:'Hajj is pilgrimage to the Sacred House in Makkah. Qur’an 3:97 connects the duty of pilgrimage with the ability to undertake it. This lesson introduces that connection. It does not assess a person’s ability, describe all the rites, or provide a personal religious ruling.',key:'Ability is part of the passage’s explanation of the duty.',pre:['What does Qur’an 3:97 connect with the duty of pilgrimage?',['The ability to undertake it','A requirement to travel every month','A preference for any holiday destination'],0],post:['Which introductory explanation best fits this passage?',['Hajj is ordinary tourism with no religious meaning','Hajj is pilgrimage, and the passage links the duty to ability','Every person must travel immediately, regardless of ability'],1],reference:'Hajj is pilgrimage to the Sacred House; Qur’an 3:97 links its duty with the ability to undertake it.',prompt:'What important qualification would you include when introducing the duty of Hajj?'}
];

const visualMaps={
 salah:{image:'salah.png',alt:'Conceptual illustration of a prayer mat in an empty prayer space.',caption:'A place for prayer. Conceptual AI illustration; not a guide to prayer movements.',branches:[['Meaning','Prescribed prayer','Worship directed to Allah'],['Key distinction','Appointed times','Not limited to moments of worry']]},
 sawm:{image:'sawm.png',alt:'Conceptual illustration of dates and a glass of water at sunset.',caption:'Dates and water evoke the setting of breaking a fast; they do not define fasting. AI illustration.',branches:[['Meaning','Fasting as worship','A prescribed religious practice'],['Purpose in this passage','Mindfulness of Allah','More than a diet or endurance test']]},
 zakat:{branches:[['Meaning','Obligatory giving','Subject to religious conditions'],['Recipients','Designated categories','Not unrestricted personal spending']]},
 sadaqah:{branches:[['In this lesson','Voluntary giving','Generosity with religious meaning'],['Read in context','The word can be broader','This lesson is an introductory use']]},
 hajj:{image:'hajj.png',alt:'Conceptual illustration of the Kaaba in a spacious courtyard.',caption:'The Kaaba, shown as a conceptual AI illustration. This is not a map or a guide to the rites.',branches:[['Meaning','Pilgrimage','To the Sacred House in Makkah'],['Qualification','Ability to undertake it','Personal circumstances need specialist advice']]}
};
function learningVisuals(l){const v=visualMaps[l.id];return `${v.image?`<figure class="lesson-picture"><img src="assets/${v.image}" alt="${v.alt}" width="1536" height="1024" loading="lazy"><figcaption>${v.caption}</figcaption></figure>`:''}<section class="concept-map" aria-label="${l.name} concept map"><div class="map-heading"><div><span class="eyebrow">CONNECT THE IDEAS</span><h3>${l.name} at a glance</h3></div><span class="map-hint">Open a branch for context</span></div><div class="map-source"><a href="${l.url}" target="_blank" rel="noopener noreferrer">${l.sourceLabel|| (l.id==='salah'?'Dorar · prayer times':'Qur’an '+l.verse)}</a><span>Source for the lesson’s key point</span></div><div class="map-stem" aria-hidden="true"></div><div class="map-root"><strong>${l.name}</strong><span lang="ar">${l.ar}</span></div><div class="map-branches">${v.branches.map((b,i)=>`<div class="map-branch"><span class="branch-label">${b[0]}</span><div class="map-node">${b[1]}</div><div class="map-stem" aria-hidden="true"></div><details class="map-leaf"><summary>${b[2]}</summary><p>${i===0?l.reference:l.key}</p></details></div>`).join('')}</div><p class="map-caption">A short learning map, not a complete account of the concept.</p></section>`;}
function journeyMap(){return `<section class="journey-map" aria-label="Learning feedback decision flow"><h3>How the learning check works</h3><div class="flow-top">Choose an answer</div><div class="map-stem" aria-hidden="true"></div><div class="flow-decision">Does it match the reference answer?</div><div class="flow-branches"><div><span class="branch-label">YES</span><div class="flow-box">Reinforce the key idea</div></div><div><span class="branch-label">NOT YET</span><div class="flow-box">Explain the missing distinction</div></div></div><div class="flow-merge" aria-hidden="true"></div><div class="flow-top">Read the source and continue learning</div><p class="map-caption">Both paths use fixed reference explanations in the current pilot.</p></section>`;}

lessons[0].url='https://dorar.net/feqhia/831';
lessons[1].url='https://dorar.net/feqhia/2624';
lessons[1].objective='Explain Sawm as fasting in worship of Allah, connected with taqwa (mindfulness of Allah), rather than merely a diet.';
lessons[1].sourceLabel='Dorar · fasting: definition and purpose';
lessons[1].sourceLocation='Definition of fasting; wisdom of fasting, first item (taqwa).';
lessons[0].objective='Explain that Salah is prescribed prayer at appointed times, rather than only a quiet moment or prayer when worried.';
lessons[2].url='https://dorar.net/feqhia/2089';
lessons[2].objective="Explain that Zakat is obligatory giving governed by religious rules with designated recipients, rather than unrestricted personal spending.";
lessons[2].sourceLabel='Dorar · definition of Zakat';
lessons[2].sourceLocation='Definition of Zakat; technical religious definition.';
lessons[2].text='Zakat is obligatory giving governed by religious rules, including designated recipients. The source defines it as worship of Allah through giving a required portion of specified wealth to designated recipients or purposes. It is not unrestricted personal spending. This introduction does not calculate anyone’s obligation or decide individual eligibility.';
lessons[2].prompt='How would you explain Zakat and its recipients to a beginner?';
lessons[3].url='https://dorar.net/feqhia/2604';
lessons[3].objective="Explain this lesson’s Sadaqah as voluntary charitable giving for the sake of Allah, rather than a compulsory payment.";
lessons[3].sourceLabel='Dorar · definition of voluntary charity';
lessons[3].sourceLocation='Definition and virtues of voluntary charity; first section: definition.';
lessons[3].text='This lesson focuses on Sadaqah as voluntary charitable giving for the sake of Allah. The source defines this voluntary charity as giving that is not obligatory and is offered for Allah. Our focus is this specific form of charity. This lesson does not decide personal obligations or judge the sincerity of an individual donation.';
lessons[3].key='Voluntary giving and its intention for Allah are the two ideas in this lesson.';
lessons[3].pre=['Which description matches voluntary Sadaqah in this lesson?',['A compulsory payment','Voluntary charitable giving for the sake of Allah','A purchase made only for personal benefit'],1];
lessons[3].post=['Which explanation preserves both ideas in this lesson?',['Giving is always compulsory','Giving only to impress people','Charity offered voluntarily for the sake of Allah'],2];
lessons[3].reference='In this lesson, Sadaqah is voluntary charitable giving for the sake of Allah; it is not a compulsory payment.';
lessons[3].prompt='How would you explain voluntary Sadaqah and its religious intention to a beginner?';
visualMaps.sadaqah.branches=[['Meaning in this lesson','Voluntary charitable giving','Not a compulsory payment'],['Intention','For the sake of Allah','Religious meaning of giving']];
lessons[4].url='https://dorar.net/feqhia/2893';
lessons[4].objective="Explain Hajj as pilgrimage to the Sacred House in Makkah as worship, and state that ability is a condition for its obligation.";
lessons[4].sourceLabel='Dorar · Hajj obligation and ability';
lessons[4].sourceLocation='Ruling on ability; first section: ability as a condition for obligation.';
lessons[4].supportingSourceUrl='https://dorar.net/feqhia/2877';
lessons[4].text='Hajj is pilgrimage to the Sacred House in Makkah as worship of Allah, with prescribed rites. Ability is a condition for its obligation. This beginner lesson focuses on pilgrimage and this ability condition; it does not describe all rites or conditions, assess personal ability, or decide whether someone must travel.';
lessons[4].reference='Hajj is pilgrimage to Makkah as worship, and ability is a condition for its obligation.';
lessons[4].prompt='How would you explain Hajj and the role of ability to a beginner?';
const aiSupported=l=>['salah','sawm','zakat','sadaqah','hajj'].includes(l.id);
const stages=['First thought','Explore','Reflect','Check'];
const fresh=()=>({stage:0,pre:null,post:null,preChecked:false,postChecked:false,reflection:'',reveal:false,done:false,ai:null,aiAnswer:'',aiBusy:false,aiError:''});
const state={current:0,records:lessons.map(fresh),view:'lesson'};
const main=document.getElementById('main');
function esc(s){return String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));}
function source(l){return `<div class="source"><strong>Read the source in context</strong><br><a href="${l.url}" target="_blank" rel="noopener noreferrer">${l.sourceLabel|| (l.id==='salah'?'Dorar · prayer times · Qur’an 4:103':'Qur’an '+l.verse+' · Quran.com')}</a>${l.supportingSourceUrl?`<br><a href="${l.supportingSourceUrl}" target="_blank" rel="noopener noreferrer">Dorar · Hajj definition · first section</a>`:''}<br><span class="sub">${l.sourceLocation?'Location: '+l.sourceLocation+' Lesson wording is a project paraphrase; specialist review is pending.':l.id==='salah'?'Location: Requirement that the prayer time has begun — Qur’an evidence and its explanation. Lesson wording is a project paraphrase; specialist review is pending.':'Lesson wording is an introductory paraphrase, not a quotation or an approved translation.'}</span></div>`;}
function selectLesson(index){if(!Number.isInteger(index)||index<0||index>=lessons.length)throw Error('Choose a valid concept.');state.current=index;state.view='lesson';render();}
function stats(){const completed=state.records.filter(r=>r.done);return {completed:completed.length,before:state.records.reduce((n,r,i)=>n+(r.done&&r.pre===lessons[i].pre[2]?1:0),0),after:state.records.reduce((n,r,i)=>n+(r.done&&r.post===lessons[i].post[2]?1:0),0)};}
function renderNav(){const s=stats();document.getElementById('concepts').innerHTML=lessons.map((l,i)=>`<button class="term ${state.view==='lesson'&&i===state.current?'active':''}" data-index="${i}" ${state.view==='lesson'&&i===state.current?'aria-current="step"':''}><span class="num">${state.records[i].done?'✓':String(i+1).padStart(2,'0')}</span><span><strong>${l.name}</strong><small>${l.label}</small></span><span class="arabic" lang="ar">${l.ar}</span></button>`).join('');document.querySelectorAll('[data-index]').forEach(b=>b.onclick=()=>selectLesson(Number(b.dataset.index)));document.getElementById('count').textContent=`${s.completed} of 5 completed`;document.getElementById('percent').textContent=`${s.completed*20}%`;document.getElementById('progress').value=s.completed;}
function render(){renderNav();if(state.view==='about')return renderAbout();if(state.view==='summary')return renderSummary();const l=lessons[state.current],r=state.records[state.current];if(r.done)return renderComplete(l,r);main.innerHTML=`<article class="card"><div class="topline"><span class="eyebrow">CONCEPT ${String(state.current+1).padStart(2,'0')} / 05</span><span class="pill">${esc(l.label)}</span></div><div class="steps">${stages.map((s,i)=>`<span class="step ${i===r.stage?'on':''}" ${i===r.stage?'aria-current="step"':''}>${i+1}. ${s}</span>`).join('')}</div><h2>${l.name} <span lang="ar" class="sub">${l.ar}</span></h2><div id="content"></div></article><div class="notice">Pilot content awaiting specialist review. Multiple-choice feedback uses fixed rules. all five concepts have an optional server AI feedback pilot; availability depends on server configuration. This is not a source of personal religious rulings.</div>`;const content=document.getElementById('content');if(r.stage===0||r.stage===3){renderQuestion(content,l,r,r.stage===3);return;}if(r.stage===1){content.innerHTML=`<p class="sub">Read the idea, then look at its source.</p><p class="lesson">${l.text}</p>${l.objective?`<div class="insight"><strong>Learning goal</strong><p>${esc(l.objective)}</p></div>`:''}${learningVisuals(l)}<div class="insight"><strong>One idea to remember</strong><br>${l.key}</div>${source(l)}<div class="actions"><button class="primary" id="next">Reflect in your own words</button><button class="quiet" id="back">Back</button></div>`;document.getElementById('next').onclick=()=>{r.stage=2;render();};document.getElementById('back').onclick=()=>{r.stage=0;render();};}else{content.innerHTML=`<p>${l.prompt}</p><label for="reflection"><strong>Your reflection</strong> <span class="sub">(optional)</span></label><textarea id="reflection" maxlength="1200" placeholder="Write a sentence or two. Avoid personal information.">${esc(r.reflection)}</textarea><p class="note">Compare your answer with the reference explanation. For each concept, you may also request optional AI learning feedback below; it is not proof of mastery.</p><button class="secondary" id="compare">${r.reveal?'Reference shown':'Show reference explanation'}</button><div id="reference" aria-live="polite">${r.reveal?`<div class="insight"><strong>Reference explanation</strong><p>${l.reference}</p><p>Does your explanation include this idea? Revise it if useful.</p></div>${source(l)}`:''}</div>${aiSupported(l)?aiPanel(r,l):''}<div class="actions"><button class="primary" id="next">Check my understanding</button><button class="quiet" id="back">Back to the lesson</button></div>`;document.getElementById('reflection').oninput=e=>{r.reflection=e.target.value;r.ai=null;r.aiError='';document.getElementById('ai-result')?.replaceChildren();};if(aiSupported(l))bindAI(r,l);document.getElementById('compare').onclick=()=>{r.reveal=true;render();};document.getElementById('next').onclick=()=>{r.stage=3;render();};document.getElementById('back').onclick=()=>{r.stage=1;render();};}}
function renderQuestion(el,l,r,isPost){const q=isPost?l.post:l.pre,key=isPost?'post':'pre',checked=isPost?r.postChecked:r.preChecked;el.innerHTML=`<p class="sub">${isPost?'Apply the idea to a new question.':'Before reading, choose the explanation that makes most sense to you.'}</p><fieldset><legend>${q[0]}</legend>${q[1].map((s,i)=>`<label class="option"><input type="radio" name="answer" value="${i}" ${r[key]===i?'checked':''} ${checked?'disabled':''}><span>${s}</span></label>`).join('')}</fieldset><div id="result" aria-live="polite">${checked?`<div class="feedback ${r[key]===q[2]?'':'review'}"><strong>${r[key]===q[2]?'That matches the key idea.':'Here is the distinction to explore.'}</strong><p>${l.reference}</p><a href="${l.url}" target="_blank" rel="noopener noreferrer">Source: Qur’an ${l.verse}</a></div>`:''}</div><div class="actions"><button class="primary" id="submit" ${r[key]===null?'disabled':''}>${checked?(isPost?'Complete this concept':'Explore the lesson'):'Check answer'}</button>${isPost?'<button class="quiet" id="back">Review the lesson</button>':''}</div><p class="note">${isPost?'One practice question is a learning check, not proof of mastery.':'Your first answer is retained for this session’s comparison.'}</p>`;el.querySelectorAll('input').forEach(b=>b.onchange=()=>{r[key]=Number(b.value);document.getElementById('submit').disabled=false;});document.getElementById('submit').onclick=()=>{if(r[key]===null)return;if(!checked){r[isPost?'postChecked':'preChecked']=true;}else if(isPost){r.done=true;}else{r.stage=1;}render();};if(isPost)document.getElementById('back').onclick=()=>{r.stage=1;render();};}
function renderComplete(l,r){main.innerHTML=`<article class="card"><span class="pill">CONCEPT COMPLETED</span><h2>A clearer view of ${l.name}.</h2><p class="lesson">${l.reference}</p><div class="metricrow"><div class="metric"><strong>${r.pre===l.pre[2]?'1':'0'} / 1</strong><span>Before the lesson</span></div><div class="metric"><strong>${r.post===l.post[2]?'1':'0'} / 1</strong><span>After the lesson</span></div><div class="metric"><strong>${stats().completed} / 5</strong><span>Concepts completed</span></div></div>${r.post!==l.post[2]?'<div class="feedback review">Revisit the key idea before continuing. Completing the activity does not mean you have mastered the concept.</div>':''}${source(l)}<div class="actions"><button class="primary" id="continue">${stats().completed<5?'Continue learning':'View session summary'}</button><button class="quiet" id="review">Read the lesson again</button></div></article>`;document.getElementById('continue').onclick=()=>{const next=state.records.findIndex(r=>!r.done);if(next<0){state.view='summary';render();}else selectLesson(next);};document.getElementById('review').onclick=()=>{main.innerHTML=`<article class="card"><h2>${l.name}</h2><p class="lesson">${l.text}</p>${l.objective?`<div class="insight"><strong>Learning goal</strong><p>${esc(l.objective)}</p></div>`:''}${learningVisuals(l)}${source(l)}<div class="actions"><button class="primary" id="return">Return to results</button></div></article>`;document.getElementById('return').onclick=render;};}
function renderSummary(){const s=stats();main.innerHTML=`<article class="card"><span class="eyebrow">THIS SESSION</span><h2>Your learning, at a glance.</h2><p class="sub">${s.completed?'Scores below include completed concepts only.':'Complete a concept to see your before-and-after checks.'}</p><div class="metricrow"><div class="metric"><strong>${s.completed} / 5</strong><span>Completed</span></div><div class="metric"><strong>${s.before} / ${s.completed}</strong><span>Correct before</span></div><div class="metric"><strong>${s.after} / ${s.completed}</strong><span>Correct after</span></div></div><div class="tablewrap"><table><thead><tr><th>Concept</th><th>Before</th><th>After</th><th>Status</th></tr></thead><tbody>${lessons.map((l,i)=>{const r=state.records[i];return `<tr><td>${l.name}</td><td>${r.done?(r.pre===l.pre[2]?'Correct':'Review'):'—'}</td><td>${r.done?(r.post===l.post[2]?'Correct':'Review'):'—'}</td><td>${r.done?'Completed':r.preChecked?'In progress':'Not started'}</td></tr>`;}).join('')}</tbody></table></div><p class="note">These are immediate practice results from different questions, not evidence of long-term learning or a controlled comparison. Refreshing the page clears your answers.</p><div class="actions"><button class="primary" id="resume">Return to learning</button></div></article>`;document.getElementById('resume').onclick=()=>selectLesson(state.current);}
function renderAbout(){main.innerHTML=`<article class="card"><span class="eyebrow">TRANSPARENCY & SOURCES</span><h2>A small, honest first step.</h2><p>Baseera is a five-concept learning pilot prepared by Dr. Osama Sayed Abdelkawi, Department of Mechanical Engineering, College of Engineering, Al-Baha University, in a personal capacity.</p><div class="notice" lang="ar" dir="rtl">هذه نسخة تجريبية لاختبار رحلة التعلم. أضيف تحليل اختياري لإجابات المفاهيم الخمسة. سُجّلت اختبارات فعلية للصلاة والصيام والزكاة والصدقة؛ اختبار الحج الفعلي قيد التنفيذ. المحتوى وملاحظات الذكاء الاصطناعي بانتظار مراجعة متخصصة.</div><h3>Baseline features and pilot status</h3><ul><li>Five short English lessons with source links, concept maps, and three conceptual illustrations.</li><li>Before-and-after multiple-choice checks and fixed explanatory feedback.</li><li>Optional written reflection with a reference explanation for self-comparison.</li><li>Session-only progress; no profile or religious classification.</li></ul>${journeyMap()}<h3>What still needs review</h3><p>The source links below were checked on 29 September 2026. The Salah timing reference was checked on 4 October against Dorar, listed on page 4 of the challenge source package. The Sawm definition and purpose reference was checked on 4 October against Dorar. The Zakat definition reference was checked on 4 October against Dorar. The voluntary Sadaqah definition was checked on 4 October against Dorar. The Hajj definition and ability-condition sources were checked on 4 October against Dorar. Lesson text is original introductory paraphrasing, not quoted translation. Detailed religious rulings are outside this pilot.</p><ul>${lessons.map(l=>`<li>${l.name}: <a href="${l.url}" target="_blank" rel="noopener noreferrer">${l.sourceLabel|| (l.id==='salah'?'Dorar · prayer times':'Qur’an '+l.verse)}</a></li>`).join('')}</ul><h3>AI integration</h3><p>Version 0.4 adds an opt-in AI feedback endpoint for all five concepts, using a curated passage retrieved by concept ID from Dorar, a source listed in the challenge package. This small pilot does not use vector search. Live developer checks and two owner-reported learner trials have been recorded for Salah. Sawm developer checks have also been recorded. Zakat developer checks have been recorded. Sadaqah developer checks have been recorded. Hajj live response quality is awaiting validation. Content and AI feedback await specialist/human review.</p><h3>Install and use offline</h3><p>Version 0.3 can be installed through a compatible browser on a phone or Windows computer. Once the sidebar confirms offline lessons are ready, this device can open the lessons, images, maps and practice checks without internet. Source links need internet. Installation availability depends on the browser and access settings.</p><h3>Privacy and version history</h3><p>Practice answers remain in the current page. If you consent and request AI feedback for any of the five concepts, that written answer is sent through our server to OpenAI for processing. The app does not save answers or log their contents; the API request sets store=false, which does not remove all provider processing/retention policies. Avoid personal information. Hosting may keep access logs. The lesson files and images can be cached on this device for offline use; remove them using the sidebar control. Hosting may process ordinary access logs. Source links open external websites with their own policies.</p><p>Version 0.1 is a pre-challenge baseline dated 29 September 2026. Version 0.2 adds illustrations and learning maps on 30 September 2026. Version 0.3 adds installation and offline support on 30 September 2026. All these versions must be disclosed separately from work completed during 4–6 October. This pilot is not the final competition deliverable.</p><button class="primary" id="resume">Return to learning</button></article>`;document.getElementById('resume').onclick=()=>selectLesson(state.current);}
document.getElementById('about').onclick=()=>{state.view='about';render();};document.getElementById('summary').onclick=()=>{state.view='summary';render();};document.getElementById('home').onclick=e=>{e.preventDefault();selectLesson(0);};render();
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'open_learning_concept',title:'Open a Baseera concept',description:'Navigate to one of the five learning concepts without answering its questions.',inputSchema:{type:'object',properties:{concept:{type:'string',enum:lessons.map(l=>l.id)}},required:['concept'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({concept})=>{const i=lessons.findIndex(l=>l.id===concept);selectLesson(i);return {concept:lessons[i].id,stage:state.records[i].stage,completed:state.records[i].done};}});document.modelContext.registerTool({name:'read_learning_progress',description:'Read the current session learning-check totals.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>stats()});}catch(e){console.warn('Optional browser tools unavailable.');}}

function aiPanel(r,l){return `<section class="insight" aria-label="AI learning feedback"><h3>Optional AI learning feedback · ${esc(l.name)} pilot</h3><p>For beginners with no prior knowledge. Feedback uses a curated source passage and still needs human review.</p><label><input type="checkbox" id="ai-consent"> I agree to send this written answer to OpenAI through Baseera. I have removed personal information.</label><p><button class="secondary" id="analyse" ${r.aiBusy?'disabled':''}>${r.aiBusy?'Analysing…':'Get feedback on my answer'}</button></p><div id="ai-result" aria-live="polite">${r.aiError?`<p>${esc(r.aiError)}</p>`:r.ai?feedbackMarkup(r.ai):''}</div></section>`;}
function feedbackMarkup(f){return `<p><strong>AI learning feedback · ${esc(f.status)}</strong></p><p><strong>What your answer shows:</strong> ${esc(f.understood)}</p><p><strong>Clarification:</strong> ${esc(f.clarification)}</p><p><strong>Try next:</strong> ${esc(f.nextStep)}</p><details><summary>Retrieved source passage</summary><p lang="ar" dir="rtl">${esc(f.source.excerpt)}</p><p>${esc(f.source.summary)}</p><p lang="ar" dir="rtl" style="text-align: right; unicode-bidi: isolate;">${esc(f.source.locator)}</p><a href="${esc(f.source.url)}" target="_blank" rel="noopener noreferrer">Dorar · ${esc(f.source.id)}</a>${f.source.supportingSource?`<p lang="ar" dir="rtl">${esc(f.source.supportingSource.excerpt)}</p><p lang="ar" dir="rtl">${esc(f.source.supportingSource.locator)}</p><a href="${esc(f.source.supportingSource.url)}" target="_blank" rel="noopener noreferrer">${esc(f.source.supportingSource.title)}</a>`:''} </details><p class="note">${esc(f.reviewStatus)}</p>`;}
function bindAI(r,l){document.getElementById('analyse').onclick=async()=>{if(r.aiBusy)return;const result=document.getElementById('ai-result');if(!document.getElementById('ai-consent').checked){result.textContent='Please consent before sending your answer.';return;}if(r.reflection.trim().length<3){result.textContent='Write a sentence first.';return;}const answer=r.reflection;r.aiBusy=true;r.aiError='';r.ai=null;const button=document.getElementById('analyse');button.disabled=true;button.textContent='Analysing…';try{const response=await fetch('/api/feedback',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({concept:l.id,answer,consent:true}),signal:AbortSignal.timeout(30000)});const data=await response.json();if(!response.ok)throw Error(data.error||'Feedback is unavailable.');if(r.reflection!==answer)return;r.ai=data;r.aiAnswer=answer;}catch(e){r.aiError=e.name==='TimeoutError'?'The request timed out. Use the reference explanation.':e.message;}finally{r.aiBusy=false;if(state.view==='lesson'&&state.records[state.current]===r&&r.stage===2)render();}};}
